// Service worker for Upbeat. Generated by tools/build.mjs — edit the template in tools/, not this file.
const VERSION = '__VERSION__';
const CACHE = 'upbeat-' + VERSION;
const FILES = __FILES__;

self.addEventListener('install', (e) => {
  e.waitUntil((async () => {
    const c = await caches.open(CACHE);
    // Add files one at a time so a single missing file does not stop the whole install.
    for (const f of FILES) { try { await c.add(new Request(f, { cache: 'reload' })); } catch (err) { console.warn('Could not cache', f); } }
  })());
});

self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter(k => k.startsWith('upbeat-') && k !== CACHE).map(k => caches.delete(k)));
    await self.clients.claim();
  })());
});

self.addEventListener('message', (e) => { if (e.data === 'skip') self.skipWaiting(); });

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return;
  // version.json is always fetched fresh so the app can tell a new version is published
  if (url.pathname.endsWith('/version.json')) { e.respondWith(fetch(req).catch(() => caches.match(req))); return; }
  e.respondWith((async () => {
    const cached = await caches.match(req, { ignoreSearch: true });
    if (cached) return cached;
    try {
      const res = await fetch(req);
      if (res.ok && (url.pathname.endsWith('.mp3') || url.pathname.endsWith('.m4a'))) { const c = await caches.open(CACHE); c.put(req, res.clone()); }
      return res;
    } catch (err) {
      if (req.mode === 'navigate') return caches.match('./index.html');
      throw err;
    }
  })());
});
